148	struct RunningRequest {
149	    id: RequestId,
150	    /// Tokens not yet emitted, stored reversed for cheap pops.
151	    pending: Vec<u32>,
152	    next_token_at: Instant,
153	    finish_reason: FinishReason,
154	    logprobs: Option<usize>,
155	}
156	
157	impl SimScheduler {
158	    fn new(config: SimulatedEngineConfig) -> Self {
159	        let spec_decode = config
160	            .spec_decode
161	            .map(|(k, _)| SpecDecodeCounters::new(k).expect("K checked at config time"));
162	        Self {
163	            config,
164	            queued: Vec::new(),
165	            running: Vec::new(),
166	            spec_decode,
167	        }
