171	        let Some(next) = self.running.iter().map(|r| r.next_token_at).min() else {
172	            return;
173	        };
174	        let now = Instant::now();
175	        if next <= now {
176	            return;
177	        }
178	        std::thread::sleep((next - now).min(WAIT_SLICE));
179	    }
