182	impl Scheduler for SimScheduler {
183	    fn submit(&mut self, request: QueuedRequest) {
184	        self.queued.push(request);
185	    }
186	
187	    fn step(&mut self, ledger: &mut RequestLedger) -> Result<()> {
188	        for QueuedRequest { id, request } in self.queued.drain(..) {
189	            if ledger.is_aborted(id) {
190	                ledger.retire(id);
191	                continue;
192	            }
193	            let prompt_len = request.prompt_tokens.len();
194	            let (pending, finish_reason) =
195	                planned_completion(&self.config, &request.prompt_tokens, request.max_tokens);
196	            ledger.admit(id);
197	            if let Some(top_k) = request.prompt_logprobs {
198	                ledger.echo_prompt(id, logprobs::prompt(&request.prompt_tokens, top_k));
199	            }
200	            if pending.is_empty() {
201	                ledger.finish(id, finish_reason);
202	                continue;
203	            }
204	            self.running.push(RunningRequest {
205	                id,
206	                pending,
207	                next_token_at: Instant::now() + self.config.ttft(prompt_len),
208	                finish_reason,
209	                logprobs: request.logprobs,
210	            });
211	        }
212	
213	        let now = Instant::now();
214	        let mut still_running = Vec::new();
215	        for mut running in self.running.drain(..) {
216	            if ledger.is_aborted(running.id) {
217	                ledger.retire(running.id);
218	                continue;
219	            }
220	            if now < running.next_token_at {
221	                still_running.push(running);
222	                continue;
223	            }
224	            let Some(token) = running.pending.pop() else {
225	                ledger.finish(running.id, running.finish_reason);
226	                continue;
227	            };
228	            let logprob = running
229	                .logprobs
230	                .map(|top_k| logprobs::completion(token, top_k));
231	            let logprobs = match logprob {
232	                Some(lp) => vec![Some(lp)],
233	                None => Vec::new(),
234	            };
235	            // Every decode step of a drafted engine is one verify step.
236	            if let (Some(counters), Some((k, accepted))) =
237	                (self.spec_decode.as_mut(), self.config.spec_decode)
238	            {
239	                counters.observe_draft(k, accepted);
240	            }
241	            ledger.push_tokens(running.id, &[token], &logprobs);
242	            if running.pending.is_empty() {
243	                ledger.finish(running.id, running.finish_reason);
244	            } else {
245	                running.next_token_at = Instant::now() + self.config.tpot();
246	                still_running.push(running);
247	            }
248	        }
249	        self.running = still_running;
250	        self.park_if_waiting();
251	        Ok(())
252	    }
253	
254	    fn metrics(&self) -> SchedulerMetrics {
255	        SchedulerMetrics {
256	            num_running_reqs: self.running.len() as u64,
257	            num_waiting_reqs: self.queued.len() as u64,
258	            spec_decode: self.spec_decode,
259	            ..SchedulerMetrics::default()
260	        }
261	    }
262	}
263	
264	/// Remaining tokens (reversed) plus the terminal reason. Empty pending means
265	/// finish immediately after admit.
266	fn planned_completion(
267	    config: &SimulatedEngineConfig,
268	    prompt_tokens: &[u32],
269	    max_tokens: usize,
270	) -> (Vec<u32>, FinishReason) {
271	    let script = &config.scripted_completion;
272	    let emit_count = if script.is_empty() {
273	        max_tokens
274	    } else {
275	        max_tokens.min(script.len())
276	    };
277	    let finish_reason = if !script.is_empty() && emit_count == script.len() {
278	        FinishReason::Stop
279	    } else {
280	        FinishReason::Length
281	    };
282	    let mut pending: Vec<u32> = if script.is_empty() {
283	        (0..emit_count)
284	            .map(|index| fake_token_id(prompt_tokens, index, config.fallback_token_id))
285	            .collect()
286	    } else {
287	        script[..emit_count].to_vec()
288	    };
289	    pending.reverse();
290	    (pending, finish_reason)
291	}
292	
293	fn fake_token_id(prompt_tokens: &[u32], index: usize, fallback_token_id: u32) -> u32 {
294	    if prompt_tokens.is_empty() {
295	        return fallback_token_id;
296	    }
297	    prompt_tokens[index % prompt_tokens.len()]
298	}
299	
300	fn duration_from_ms(ms: f64) -> Duration {
301	    Duration::from_secs_f64(ms / 1000.0)
302	}
