409	/// One expected exposition line: metric name, `engine` label, any further
410	/// labels, and the value it must carry.
411	type ExpectedMetric<'a> = (&'a str, &'a str, &'a [(&'a str, &'a str)], f64);
412	
413	/// [`wait_for_metrics`] plus arbitrary extra labels, for families keyed by more
414	/// than engine and model — the per-position spec-decode counter adds `position`.
415	async fn wait_for_labeled_metrics(
416	    client: &Client,
417	    base_url: &str,
418	    expected: &[ExpectedMetric<'_>],
419	    model_name: &str,
420	) -> Result<()> {
421	    let metrics_url = format!("{base_url}/metrics");
422	    let deadline = tokio::time::Instant::now() + Duration::from_secs(10);
423	    let mut last_metrics = String::new();
424	    loop {
425	        if tokio::time::Instant::now() >= deadline {
426	            bail!("timed out waiting for scheduler metrics at {metrics_url}:\n{last_metrics}");
427	        }
428	
429	        if let Ok(response) = client.get(&metrics_url).send().await {
430	            if let Ok(response) = response.error_for_status() {
431	                if let Ok(metrics) = response.text().await {
432	                    let all_found =
433	                        expected
434	                            .iter()
435	                            .all(|(metric, engine, labels, expected_value)| {
436	                                metrics.lines().any(|line| {
437	                                    line.starts_with(metric)
438	                                        && line.contains(&format!("engine=\"{engine}\""))
439	                                        && line.contains(&format!("model_name=\"{model_name}\""))
440	                                        && labels.iter().all(|(name, value)| {
441	                                            line.contains(&format!("{name}=\"{value}\""))
442	                                        })
443	                                        && line
444	                                            .rsplit_once(' ')
445	                                            .and_then(|(_, value)| value.parse::<f64>().ok())
446	                                            .is_some_and(|value| {
447	                                                (value - expected_value).abs() < 1e-9
448	                                            })
449	                                })
450	                            });
451	                    if all_found {
452	                        return Ok(());
453	                    }
454	                    last_metrics = metrics;
455	                }
456	            }
457	        }
458	        tokio::time::sleep(Duration::from_millis(50)).await;
459	    }
460	}
