901	fn parse_terminal_sse_chunks(stream: &str) -> Result<Vec<Value>> {
902	    let normalized = stream.replace("\r\n", "\n").replace('\r', "\n");
903	    let mut payloads = Vec::new();
904	    let mut data_lines = Vec::new();
905	
906	    for line in normalized.split_terminator('\n') {
907	        if line.is_empty() {
908	            if !data_lines.is_empty() {
909	                payloads.push(data_lines.join("\n"));
910	                data_lines.clear();
911	            }
912	            continue;
913	        }
914	        if line.starts_with(':') {
915	            continue;
916	        }
917	
918	        let (field, value) = line.split_once(':').unwrap_or((line, ""));
919	        if field == "data" {
920	            data_lines.push(value.strip_prefix(' ').unwrap_or(value));
921	        }
922	    }
923	    if !data_lines.is_empty() {
924	        bail!("streaming response ended before its final SSE event was dispatched: {stream}");
925	    }
926	
927	    let done_count = payloads
928	        .iter()
929	        .filter(|payload| payload.as_str() == "[DONE]")
930	        .count();
931	    if done_count != 1 {
932	        bail!("streaming response must contain exactly one data: [DONE]: {stream}");
933	    }
934	    if payloads.last().map(String::as_str) != Some("[DONE]") {
935	        bail!("streaming response must end with data: [DONE]: {stream}");
936	    }
937	
938	    payloads[..payloads.len() - 1]
939	        .iter()
940	        .map(|payload| serde_json::from_str(payload))
941	        .collect::<std::result::Result<Vec<_>, _>>()
942	        .context("failed to parse streaming chunks")
943	}
